    if not purple_pants_patches: return pink_shirt_patches[0]
    for patch in pink_shirt_patches:
        if patch.overlaps_with(purple_pants_patches[0].left, purple_pants_patches[0].lower, purple_pants_patches[0].right, purple_pants_patches[0].upper):
            return patch
    return pink_shirt_patches[0]
